eventTypes.schema:
{
 "fields": [
  {
   "name": "orderId",
   "type": "string",
   "doc": "Order identifier, unique per sales channel"
  },
  {
   "name": "amount",
   "type": "double",
   "doc": "Order total in the order's currency, tax included"
  },
  {
   "name": "placedAt",
   "type": "long",
   "doc": "When the order was placed, epoch milliseconds UTC"
  }
 ],
 "type": "record",
 "name": "Orders",
 "doc": "An order as placed, before fulfilment."
}

{
 "fields": [
  {
   "name": "customerId",
   "type": "string",
   "doc": "Customer identifier, unique per source system"
  },
  {
   "name": "registeredAt",
   "type": "long",
   "doc": "When the customer registered, epoch milliseconds UTC"
  },
  {
   "name": "region",
   "type": "string",
   "doc": "Sales region code"
  },
  {
   "name": "segment",
   "type": "string",
   "doc": "Marketing segment"
  }
 ],
 "type": "record",
 "name": "Customers"
}

